CREATE TABLE [sales].[CustomerDocuments] ([DocumentId] UNIQUEIDENTIFIER NOT NULL CONSTRAINT [DF_CustomerDocuments_Id] DEFAULT NEWSEQUENTIALID(),[CustomerId] UNIQUEIDENTIFIER NOT NULL,[DocumentType] NVARCHAR(50) NOT NULL,[FileName] NVARCHAR(255) NOT NULL,[ContentType] NVARCHAR(100) NOT NULL,[DocumentData] VARBINARY(MAX) NOT NULL,[UploadedOn] DATETIMEOFFSET NOT NULL CONSTRAINT [DF_CustomerDocuments_Uploaded] DEFAULT SYSUTCDATETIME(),[UploadedBy] NVARCHAR(256) NULL,[IsDeleted] BIT NOT NULL CONSTRAINT [DF_CustomerDocuments_Deleted] DEFAULT 0,[RowVersion] ROWVERSION NOT NULL,CONSTRAINT [PK_CustomerDocuments] PRIMARY KEY([DocumentId]),CONSTRAINT [FK_CustomerDocuments_Customers] FOREIGN KEY([CustomerId]) REFERENCES [sales].[Customers]([CustomerId]) ON DELETE CASCADE,CONSTRAINT [CK_CustomerDocuments_Type] CHECK([DocumentType] IN('GST Certificate','PAN','Agreement','Other')));
GO
CREATE INDEX [IX_CustomerDocuments_CustomerId] ON [sales].[CustomerDocuments]([CustomerId],[IsDeleted]);
